#define Z_T2558_INDEX_EMPTY (-1)
#define Z_T2558_INDEX_DELETED (-2)

typedef struct {
    uint8_t alive;
    uint64_t hash;
    z_t2553_t key;
    z_t63_t value;
} z_t2558_entry_t;

typedef struct z_t2558_t {
    uint64_t capacity;
    uint64_t length;
    uint64_t entries_len;
    uint64_t entries_cap;
    int64_t* indices;
    z_t2558_entry_t* entries;
} z_t2558_t;

static uint64_t z_t2558_hash_key(z_t2553_t _key);
